    fn refresh_agent_interaction(&mut self) {
        match (
            self.application.agent_interaction_settings(),
            self.application.custom_subagent_catalog(),
        ) {
            (Ok(settings), Ok(catalog)) => {
                self.agent_interaction_settings = settings;
                self.custom_agents = catalog;
                if self.editing_custom_agent.as_ref().is_some_and(|agent_id| {
                    !self
                        .custom_agents
                        .agents
                        .iter()
                        .any(|agent| &agent.id == agent_id)
                }) {
                    self.clear_custom_agent_editor();
                }
                self.agent_interaction_error = None;
            }
            (Err(error), _) | (_, Err(error)) => {
                eprintln!("failed to refresh Native Agent interaction settings: {error}");
                self.agent_interaction_error = Some("无法读取 Agent 设置，请稍后重试。".to_owned());
            }
        }
    }

    fn toggle_agent_interaction_setting(&mut self, toggle: AgentInteractionToggle) {
        let mut update =
            DesktopAgentInteractionSettingsUpdate::from_settings(&self.agent_interaction_settings);
        match toggle {
            AgentInteractionToggle::NonInterrupt => {
                update.non_interrupt_mode = !update.non_interrupt_mode
            }
            AgentInteractionToggle::Debug => update.debug = !update.debug,
            AgentInteractionToggle::Subagents => {
                update.subagent_mode.enabled = !update.subagent_mode.enabled
            }
            AgentInteractionToggle::AutoTurn => {
                update.auto_turn_decision.enabled = !update.auto_turn_decision.enabled
            }
            AgentInteractionToggle::AutoModelTier => {
                update.auto_turn_decision.allow_model_tier =
                    !update.auto_turn_decision.allow_model_tier
            }
            AgentInteractionToggle::AutoReasoningEffort => {
                update.auto_turn_decision.allow_reasoning_effort =
                    !update.auto_turn_decision.allow_reasoning_effort
            }
            AgentInteractionToggle::AutoPlanMode => {
                update.auto_turn_decision.allow_plan_mode =
                    !update.auto_turn_decision.allow_plan_mode
            }
            AgentInteractionToggle::AutoGoalMode => {
                update.auto_turn_decision.allow_goal_mode =
                    !update.auto_turn_decision.allow_goal_mode
            }
            AgentInteractionToggle::AutoSessionFork => {
                update.auto_turn_decision.allow_session_fork =
                    !update.auto_turn_decision.allow_session_fork
            }
        }
        match self.application.save_agent_interaction_settings(update) {
            Ok(settings) => {
                self.agent_interaction_settings = settings;
                self.custom_agents.revision = self.agent_interaction_settings.revision;
                self.agent_interaction_error = None;
            }
            Err(error) => {
                eprintln!("failed to save Native Agent interaction settings: {error}");
                self.agent_interaction_error = Some(agent_interaction_error_message(&error));
            }
        }
    }

    fn edit_custom_agent(&mut self, agent_id: &str) {
        let Some(agent) = self
            .custom_agents
            .agents
            .iter()
            .find(|agent| agent.id == agent_id)
            .cloned()
        else {
            self.agent_interaction_error = Some("找不到要编辑的 Agent。".to_owned());
            return;
        };
        self.custom_agent_editor_open = true;
        self.editing_custom_agent = Some(agent.id);
        self.custom_agent_name = agent.name;
        self.custom_agent_description = agent.description;
        self.custom_agent_instruction.set_text(&agent.instruction);
        self.agent_interaction_error = None;
    }

    fn clear_custom_agent_editor(&mut self) {
        self.custom_agent_editor_open = false;
        self.editing_custom_agent = None;
        self.custom_agent_name.clear();
        self.custom_agent_description.clear();
        self.custom_agent_instruction.clear();
        self.agent_interaction_error = None;
    }

    fn begin_new_custom_agent(&mut self) {
        self.clear_custom_agent_editor();
        self.custom_agent_editor_open = true;
    }

    fn save_custom_agent(&mut self) {
        let input = DesktopCustomSubagentUpsert {
            expected_revision: self.custom_agents.revision,
            id: self.editing_custom_agent.clone(),
            name: self.custom_agent_name.clone(),
            description: self.custom_agent_description.clone(),
            instruction: self.custom_agent_instruction.text(),
            enabled: self
                .editing_custom_agent
                .as_ref()
                .and_then(|agent_id| {
                    self.custom_agents
                        .agents
                        .iter()
                        .find(|agent| &agent.id == agent_id)
                })
                .is_none_or(|agent| agent.enabled),
        };
        match self.application.upsert_custom_subagent(input) {
            Ok(_) => {
                self.clear_custom_agent_editor();
                self.refresh_agent_interaction();
            }
            Err(error) => {
                eprintln!("failed to save Native custom Agent: {error}");
                self.agent_interaction_error = Some(agent_interaction_error_message(&error));
            }
        }
    }

    fn toggle_custom_agent(&mut self, agent_id: &str) {
        let Some(agent) = self
            .custom_agents
            .agents
            .iter()
            .find(|agent| agent.id == agent_id)
            .cloned()
        else {
            self.agent_interaction_error = Some("找不到要更新的 Agent。".to_owned());
            return;
        };
        match self
            .application
            .upsert_custom_subagent(DesktopCustomSubagentUpsert {
                expected_revision: self.custom_agents.revision,
                id: Some(agent.id),
                name: agent.name,
                description: agent.description,
                instruction: agent.instruction,
                enabled: !agent.enabled,
            }) {
            Ok(_) => self.refresh_agent_interaction(),
            Err(error) => {
                eprintln!("failed to toggle Native custom Agent: {error}");
                self.agent_interaction_error = Some(agent_interaction_error_message(&error));
            }
        }
    }

    fn delete_custom_agent(&mut self, agent_id: &str) {
        match self
            .application
            .delete_custom_subagent(self.custom_agents.revision, agent_id)
        {
            Ok(catalog) => {
                self.agent_interaction_settings.revision = catalog.revision;
                self.custom_agents = catalog;
                if self.editing_custom_agent.as_deref() == Some(agent_id) {
                    self.clear_custom_agent_editor();
                }
                self.agent_interaction_error = None;
            }
            Err(error) => {
                eprintln!("failed to delete Native custom Agent: {error}");
                self.agent_interaction_error = Some(agent_interaction_error_message(&error));
            }
        }
    }

    fn selected_provider_supports_api_key(&self) -> bool {
        self.selected_provider.as_ref().is_some_and(|selected| {
            self.provider.providers.iter().any(|provider| {
                &provider.provider_id == selected
                    && provider
                        .supported_kinds
                        .contains(&DesktopCredentialKind::ApiKey)
            })
        })
    }

    fn save_provider_credential(&mut self) {
        if self.provider_busy() || self.provider_secret.trim().is_empty() {
            return;
        }
        let Some(provider_id) = self.selected_provider.clone() else {
            self.provider_error = Some("当前没有可配置的模型服务。".to_owned());
            return;
        };
        if !self.selected_provider_supports_api_key() {
            self.provider_error = Some("当前模型服务不支持 API Key 凭据。".to_owned());
            return;
        }
        let secret = DesktopSecret::new(std::mem::take(&mut self.provider_secret).into_bytes());
        self.provider_secrets.stage(secret);
        self.start_provider_operation(CredentialRequest::SaveApiKey { provider_id });
    }

    fn pick_data_import_source(&mut self) {
        if self.data_import.busy || self.data_import.restart_required {
            return;
        }
        let request = DesktopFileDialogRequest {
            dialog_id: "data-import-source".to_owned(),
            title: Some("选择旧版 LiliaCode 数据目录".to_owned()),
            initial_directory: self.home.parent().map(PathBuf::from),
            filters: Vec::new(),
            select_directories: true,
            multiple: false,
        };
        match self
            .application
            .execute_host(DesktopHostAction::FileDialog(request))
        {
            Ok(DesktopHostResult::FileDialogSelection(paths)) => {
                if let Some(path) = paths.into_iter().next() {
                    self.start_data_import_plan(path);
                }
            }
            Ok(_) => self.data_import.set_error("无法读取所选目录，请重新选择。"),
            Err(error) => {
                eprintln!("LiliaCode data import picker failed: {error}");
                self.data_import
                    .set_error("无法打开目录选择器，请稍后重试。")
            }
        }
    }

    fn start_data_import_plan(&mut self, source_home: PathBuf) {
        if self.data_import.busy || self.data_import.restart_required {
            return;
        }
        if self
            .turn_state
            .as_ref()
            .is_some_and(|(_, state)| turn_state_is_active(state))
        {
            self.data_import
                .set_error("请先等待当前任务结束或将其停止，再开始导入。");
            return;
        }
        match crate::pending_import::target_is_empty(&self.home) {
            Ok(true) => {}
            Ok(false) if debug_import_assume_empty() => {}
            Ok(false) => {
                self.data_import
                    .set_error("当前 LiliaCode 已有数据，无法导入旧版数据。");
                return;
            }
            Err(error) => {
                eprintln!("LiliaCode import target inspection failed: {error}");
                self.data_import
                    .set_error("无法确认当前数据状态，请稍后重试。");
                return;
            }
        }
        self.data_import.reset_for_plan(source_home.clone());
        let staging_home = match crate::pending_import::create_staging_home(&self.home) {
            Ok(home) => home,
            Err(error) => {
                eprintln!("LiliaCode import staging directory failed: {error}");
                self.data_import.fail("无法准备导入目录，请稍后重试。");
                return;
            }
        };
        let target = match DesktopApplicationConfig::new(
            staging_home,
            self.data_import_target_identity.clone(),
        ) {
            Ok(target) => target,
            Err(error) => {
                eprintln!("LiliaCode import staging configuration failed: {error}");
                self.data_import.fail("无法准备导入，请稍后重试。");
                return;
            }
        };
        let source_identity = match legacy_instance_identity(&source_home) {
            Ok(identity) => identity,
            Err(error) => {
                self.data_import.fail(error);
                return;
            }
        };
        let source = match DesktopApplicationConfig::new(source_home, source_identity) {
            Ok(source) => source,
            Err(error) => {
                eprintln!("LiliaCode import source configuration failed: {error}");
                self.data_import.fail("所选目录无法使用，请重新选择。");
                return;
            }
        };
        let service = DesktopDataImportService::new(target, Arc::new(NativeDesktopHost));
        self.submit_import_job(
            lilia_feature_import::PLAN_PROTOCOL,
            ImportCommand::Plan { service, source },
            "无法开始检查，请稍后重试。",
        );
    }

    fn start_data_import_execution(&mut self) {
        let Some(plan) = self.data_import.plan.clone() else {
            return;
        };
        if !self.data_import.can_execute() {
            return;
        }
        let target = match DesktopApplicationConfig::new(
            plan.target_home.clone(),
            self.data_import_target_identity.clone(),
        ) {
            Ok(target) => target,
            Err(error) => {
                eprintln!("LiliaCode import execution configuration failed: {error}");
                self.data_import.fail("无法准备导入，请重新生成计划。");
                return;
            }
        };
        let credential_decision = if self.data_import.credentials_confirmed {
            CredentialImportDecision::Confirmed
        } else {
            CredentialImportDecision::Denied
        };
        let service = DesktopDataImportService::new(target, Arc::new(NativeDesktopHost));
        self.submit_import_job(
            lilia_feature_import::EXECUTE_PROTOCOL,
            ImportCommand::Execute {
                service,
                plan: Box::new(plan),
                options: DesktopImportExecutionOptions {
                    credential_decision,
                },
            },
            "无法开始导入，请稍后重试。",
        );
    }

    /// Stages one import step and submits the job that claims it. The step runs
    /// against an application config and a live host handle, neither of which
    /// belongs in a payload, so only the ticket travels.
    fn submit_import_job(&mut self, protocol: &str, command: ImportCommand, failure_notice: &str) {
        let ticket = self.import_exchange.park(command);
        let request = JobRequest::new(
            protocol,
            serde_json::to_value(lilia_feature_import::ImportRequest::new(ticket))
                .expect("an import request is representable as JSON"),
        )
        .in_slot(lilia_feature_import::import_slot());

        match self.kernel.kernel().jobs().submit(request) {
            Ok(handle) => {
                self.active_import_job = Some((handle.id(), ticket));
                self.data_import.begin(handle.id());
            }
            Err(error) => {
                eprintln!("failed to submit the LiliaCode import job: {error}");
                self.import_exchange.discard(ticket);
                self.data_import.fail(failure_notice);
            }
        }
    }

    fn apply_import_job(&mut self, job_id: JobId, planning: bool, state: JobState) {
        let output = match state {
            JobState::Pending | JobState::Running { .. } => return,
            JobState::Completed { output } => output,
            JobState::Failed { message } => {
                self.clear_import_job();
                self.data_import.fail(message);
                return;
            }
            _ => {
                self.clear_import_job();
                return;
            }
        };
        self.clear_import_job();
        if planning {
            let result = serde_json::from_value::<DesktopImportPlan>(output)
                .map_err(|_| "无法读取导入计划。".to_owned());
            self.data_import.finish_plan(job_id, result);
            return;
        }
        match serde_json::from_value::<DesktopImportReport>(output) {
            Ok(report) => self.finish_data_import(job_id, report),
            Err(_) => self.data_import.fail("无法读取导入结果。"),
        }
    }

    fn clear_import_job(&mut self) {
        if let Some((_, ticket)) = self.active_import_job.take() {
            self.import_exchange.discard(ticket);
        }
    }

    fn finish_data_import(&mut self, job_id: JobId, report: DesktopImportReport) {
        if !self.data_import.finish_execute(job_id, report.clone()) {
            return;
        }
        match crate::pending_import::schedule(&self.home, &report) {
            Ok(restart_required) => self.data_import.set_restart_required(restart_required),
            Err(error) => {
                eprintln!("LiliaCode import activation scheduling failed: {error}");
                self.data_import
                    .set_error("数据已完成检查，但无法安排重启激活；请重试导入。")
            }
        }
    }

    fn reset_data_import(&mut self) {
        if self.data_import.busy || self.data_import.restart_required {
            return;
        }
        if let Some(plan) = &self.data_import.plan {
            if let Err(error) =
                crate::pending_import::discard_staging(&self.home, &plan.target_home)
            {
                eprintln!("LiliaCode import staging cleanup failed: {error}");
                self.data_import
                    .set_error("无法清理本次导入，请重启应用后再试。");
                return;
            }
        }
        self.data_import.reset();
    }

    fn restart_after_data_import(&mut self) {
        if !self.data_import.restart_required {
            return;
        }
        match crate::pending_import::launch_helper() {
            Ok(()) => self.exit_requested = true,
            Err(error) => {
                eprintln!("LiliaCode import restart failed: {error}");
                self.data_import
                    .set_error("无法重启应用，请关闭并重新打开以完成导入。")
            }
        }
    }

    fn start_provider_operation(&mut self, request: CredentialRequest) {
        if self.provider_busy() {
            return;
        }
        let request = JobRequest::new(
            lilia_feature_provider::CREDENTIAL_PROTOCOL,
            serde_json::to_value(request).expect("a credential request is representable as JSON"),
        )
        .in_slot(lilia_feature_provider::credential_slot());

        self.provider_error = None;
        match self.kernel.kernel().jobs().submit(request) {
            Ok(handle) => self.active_provider_job = Some(handle.id()),
            Err(error) => {
                eprintln!("failed to submit the LiliaCode provider job: {error}");
                self.provider_secrets.discard();
                self.provider_error = Some("无法启动凭据操作，请稍后重试。".to_owned());
            }
        }
    }

    fn apply_provider_job(&mut self, state: JobState) {
        match state {
            JobState::Pending | JobState::Running { .. } => return,
            JobState::Completed { .. } => {
                self.active_provider_job = None;
                self.provider_error = None;
            }
            JobState::Failed { message } => {
                self.active_provider_job = None;
                self.provider_error = Some(message);
            }
            JobState::Cancelled | JobState::Superseded => {
                self.active_provider_job = None;
            }
        }
        self.provider_secrets.discard();
        self.refresh_provider();
    }

    fn refresh_quota(&mut self) {
        if self.quota_busy() {
            return;
        }
        let request = JobRequest::new(
            lilia_feature_usage::QUOTA_PROTOCOL,
            serde_json::to_value(QuotaUsageStatsInput {
                days: Some(self.quota_days),
                backend: Some(self.quota_backend.clone()),
            })
            .expect("a quota request is representable as JSON"),
        )
        .in_slot(lilia_feature_usage::quota_slot());

        self.quota_error = None;
        match self.kernel.kernel().jobs().submit(request) {
            Ok(handle) => self.active_quota_job = Some(handle.id()),
            Err(error) => {
                eprintln!("failed to submit the LiliaCode quota job: {error}");
                self.quota_error = Some("无法刷新本地用量，请稍后重试。".to_owned());
            }
        }
    }

    fn apply_quota_job(&mut self, state: JobState) {
        match state {
            JobState::Pending | JobState::Running { .. } => {}
            JobState::Completed { output } => {
                self.active_quota_job = None;
                match serde_json::from_value::<QuotaUsageStats>(output) {
                    Ok(stats) => {
                        self.quota_days = stats.days;
                        self.quota_backend = stats.backend.clone();
                        self.quota_usage = Some(stats);
                        self.quota_error = None;
                    }
                    Err(error) => self.quota_error = Some(format!("无法读取用量报告：{error}")),
                }
            }
            JobState::Failed { message } => {
                self.active_quota_job = None;
                self.quota_error = Some(message);
            }
            JobState::Cancelled | JobState::Superseded => {
                self.active_quota_job = None;
            }
        }
    }

