fn composer_conversation_query(content: &str) -> Option<String> {
    composer_trailing_trigger_query(content, '#', true)
}

fn shell_timeline_row(
    item: &TaskTimelineItem,
    expanded: bool,
    can_retry: bool,
) -> crate::runtime_shell::ShellTimelineRow {
    let full = item
        .markdown
        .clone()
        .or_else(|| item.summary.clone())
        .filter(|text| !text.trim().is_empty())
        .unwrap_or_else(|| item.title.clone());
    let preview = item
        .summary
        .clone()
        .filter(|text| !text.trim().is_empty())
        .unwrap_or_else(|| item.title.clone());
    let can_expand = item.markdown.as_ref().is_some_and(|markdown| {
        item.summary
            .as_ref()
            .is_some_and(|summary| summary != markdown)
            || item.title != *markdown
    });
    crate::runtime_shell::ShellTimelineRow {
        id: item.id.clone(),
        markdown: if expanded || !can_expand {
            full
        } else {
            preview
        },
        expanded,
        can_expand,
        can_retry,
        can_copy: item
            .markdown_plain_text
            .as_ref()
            .or(item.markdown.as_ref())
            .is_some_and(|text| !text.trim().is_empty()),
    }
}

fn coding_hit_key(hit: &DesktopWorkspaceCodeSearchHit) -> String {
    format!("{}:{}", hit.project_id.as_str(), hit.hit.path)
}

fn composer_context_query(content: &str) -> Option<String> {
    let query = composer_trailing_trigger_query(content, '@', false)?;
    if query.chars().any(char::is_whitespace) && !is_absolute_context_path(&query) {
        return None;
    }
    Some(query)
}

fn composer_content_with_trigger(content: &str, marker: char) -> String {
    if content.ends_with(marker) {
        return content.to_owned();
    }
    let mut content = content.to_owned();
    if !content.is_empty() && !content.chars().last().is_some_and(char::is_whitespace) {
        content.push(' ');
    }
    content.push(marker);
    content
}

fn composer_trailing_trigger_query(
    content: &str,
    marker: char,
    allow_whitespace: bool,
) -> Option<String> {
    let start = content.rfind(marker)?;
    let query = &content[start + marker.len_utf8()..];
    if query.len() > 240 || query.contains('\n') || query.contains('\r') {
        return None;
    }
    if !allow_whitespace && query.chars().any(char::is_whitespace) {
        return Some(query.to_owned());
    }
    Some(query.trim().to_owned())
}

fn is_absolute_context_path(value: &str) -> bool {
    let value = value.trim();
    let bytes = value.as_bytes();
    (bytes.len() >= 3
        && bytes[1] == b':'
        && bytes[0].is_ascii_alphabetic()
        && matches!(bytes[2], b'/' | b'\\'))
        || value.starts_with("\\\\")
        || value.starts_with('/')
}

fn composer_content_without_trigger(content: &str, marker: char) -> Option<String> {
    let start = content.rfind(marker)?;
    let mut prefix = content[..start].to_owned();
    if !prefix.is_empty() && !prefix.chars().last().is_some_and(char::is_whitespace) {
        prefix.push(' ');
    }
    Some(prefix)
}

fn pending_review_target_id(kind: PendingReviewTargetKind) -> &'static str {
    match kind {
        PendingReviewTargetKind::UncommittedChanges => "uncommitted",
        PendingReviewTargetKind::BaseBranch => "branch",
        PendingReviewTargetKind::Commit => "commit",
    }
}

#[cfg(debug_assertions)]
fn review_workflow_target_ids(
    window_id: HostedWindowId,
    pending: &PendingReviewSlashWorkflow,
) -> Vec<String> {
    let mut targets = [
        PendingReviewTargetKind::UncommittedChanges,
        PendingReviewTargetKind::BaseBranch,
        PendingReviewTargetKind::Commit,
    ]
    .into_iter()
    .map(|kind| target_ids::review_workflow_target(window_id.0, pending_review_target_id(kind)))
    .collect::<Vec<_>>();
    targets.push(target_ids::review_workflow_cancel(window_id.0));
    if pending.target_kind != PendingReviewTargetKind::UncommittedChanges {
        targets.push(target_ids::review_workflow_target_input(window_id.0));
    }
    if pending.target_kind == PendingReviewTargetKind::UncommittedChanges
        || !pending.target_value.trim().is_empty()
    {
        targets.push(target_ids::review_workflow_submit(window_id.0));
    }
    targets
}

