fn turn_state_is_active(state: &DesktopTurnState) -> bool {
    matches!(
        state,
        DesktopTurnState::Starting
            | DesktopTurnState::Running
            | DesktopTurnState::WaitingApproval { .. }
            | DesktopTurnState::ResolvingApproval
            | DesktopTurnState::WaitingInteraction { .. }
            | DesktopTurnState::ResolvingInteraction
    )
}

fn restored_turn_state(
    runtime: &DesktopTaskRuntimeSnapshot,
    pending: &[PendingActionView],
) -> Option<(String, DesktopTurnState)> {
    let turn_id = runtime.turn_id.clone()?;
    let state = match runtime.phase.as_str() {
        "starting" => DesktopTurnState::Starting,
        "running" => DesktopTurnState::Running,
        "waiting_approval" => {
            let request_id = pending
                .iter()
                .rev()
                .find(|pending| {
                    pending.status == PendingProjectionStatus::Open
                        && pending.kind == "permission_approval"
                })
                .map(|pending| pending.request_id.clone());
            DesktopTurnState::WaitingApproval {
                request_id,
                error: None,
            }
        }
        "waiting_interaction" => {
            let interaction = pending.iter().rev().find(|pending| {
                pending.status == PendingProjectionStatus::Open
                    && matches!(
                        pending.kind.as_str(),
                        "ask_user"
                            | "plan_approval"
                            | "tool_consent"
                            | "mcp_elicitation"
                            | "architecture_change"
                    )
            });
            DesktopTurnState::WaitingInteraction {
                request_id: interaction.map(|pending| pending.request_id.clone()),
                kind: interaction.map(|pending| pending.kind.clone()),
                error: None,
            }
        }
        _ => return None,
    };
    Some((turn_id, state))
}

#[cfg(debug_assertions)]
fn turn_state_key(state: &DesktopTurnState) -> &'static str {
    match state {
        DesktopTurnState::Queued { .. } => "queued",
        DesktopTurnState::Starting => "starting",
        DesktopTurnState::Running => "running",
        DesktopTurnState::WaitingApproval { .. } => "waiting_approval",
        DesktopTurnState::ResolvingApproval => "resolving_approval",
        DesktopTurnState::WaitingInteraction { .. } => "waiting_interaction",
        DesktopTurnState::ResolvingInteraction => "resolving_interaction",
        DesktopTurnState::Completed => "completed",
        DesktopTurnState::Cancelled => "cancelled",
        DesktopTurnState::Failed { .. } => "failed",
    }
}

#[cfg(debug_assertions)]
fn debug_turn_state_key(
    runtime: Option<&DesktopTaskRuntimeSnapshot>,
    pending: &[PendingActionView],
    event_state: Option<&DesktopTurnState>,
) -> Option<&'static str> {
    runtime
        .and_then(|runtime| restored_turn_state(runtime, pending))
        .map(|(_, state)| turn_state_key(&state))
        .or_else(|| event_state.map(turn_state_key))
}

#[cfg(debug_assertions)]
fn turn_state_error(state: &DesktopTurnState) -> Option<&str> {
    match state {
        DesktopTurnState::WaitingApproval {
            error: Some(error), ..
        }
        | DesktopTurnState::WaitingInteraction {
            error: Some(error), ..
        }
        | DesktopTurnState::Failed { message: error } => Some(error),
        _ => None,
    }
}

