fn quote_timeline_text(text: &str) -> String {
    let normalized = text.replace("\r\n", "\n").replace('\r', "\n");
    let normalized = normalized.trim();
    if normalized.is_empty() {
        return String::new();
    }
    format!(
        "{}\n\n",
        normalized
            .lines()
            .map(|line| format!("> {line}"))
            .collect::<Vec<_>>()
            .join("\n")
    )
}

fn popup_question_text(text: &str) -> String {
    format!(
        "请基于这段 Agent 回复继续提问：\n\n{}",
        quote_timeline_text(text)
    )
}

fn composer_draft_title(composer: &DesktopComposerState) -> String {
    let normalized = composer
        .content
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    let source = if normalized.is_empty() {
        composer
            .attachments
            .first()
            .map(|attachment| attachment.name.trim())
            .filter(|name| !name.is_empty())
            .unwrap_or("附件")
            .to_owned()
    } else {
        normalized
    };
    let mut characters = source.chars();
    let mut title = characters.by_ref().take(30).collect::<String>();
    if characters.next().is_some() {
        title.push('…');
    }
    title
}

fn turn_state_color(state: &DesktopTurnState, colors: Colors) -> nana_ui::Color {
    match state {
        DesktopTurnState::Completed => colors.success,
        DesktopTurnState::Cancelled | DesktopTurnState::Failed { .. } => colors.danger,
        DesktopTurnState::WaitingApproval { .. } | DesktopTurnState::WaitingInteraction { .. } => {
            colors.warning
        }
        DesktopTurnState::Queued { .. }
        | DesktopTurnState::Starting
        | DesktopTurnState::Running
        | DesktopTurnState::ResolvingApproval
        | DesktopTurnState::ResolvingInteraction => colors.muted,
    }
}

