pub(crate) fn parse_civil_date_update(value: &str) -> Result<MilestoneDueDateUpdate, String> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(MilestoneDueDateUpdate::Clear);
    }
    let mut parts = value.split('-');
    let (Some(year), Some(month), Some(day), None) =
        (parts.next(), parts.next(), parts.next(), parts.next())
    else {
        return Err("截止日期需使用 YYYY-MM-DD 格式。".to_owned());
    };
    let year = year
        .parse::<i32>()
        .map_err(|_| "截止日期年份无效。".to_owned())?;
    let month = month
        .parse::<u32>()
        .map_err(|_| "截止日期月份无效。".to_owned())?;
    let day = day
        .parse::<u32>()
        .map_err(|_| "截止日期日期无效。".to_owned())?;
    if !(1..=12).contains(&month) || day == 0 || day > days_in_month(year, month) {
        return Err("截止日期不是有效的日历日期。".to_owned());
    }
    let millis = days_from_civil(year, month, day)
        .checked_mul(86_400_000)
        .ok_or_else(|| "截止日期超出支持范围。".to_owned())?;
    Ok(MilestoneDueDateUpdate::Set(millis))
}

pub(crate) fn format_civil_date(timestamp_millis: i64) -> String {
    let days = timestamp_millis.div_euclid(86_400_000);
    let (year, month, day) = civil_from_days(days);
    format!("{year:04}-{month:02}-{day:02}")
}

fn days_in_month(year: i32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if year % 400 == 0 || (year % 4 == 0 && year % 100 != 0) => 29,
        2 => 28,
        _ => 0,
    }
}

fn days_from_civil(year: i32, month: u32, day: u32) -> i64 {
    let adjusted_year = i64::from(year) - i64::from(month <= 2);
    let era = adjusted_year.div_euclid(400);
    let year_of_era = adjusted_year - era * 400;
    let shifted_month = i64::from(month) + if month > 2 { -3 } else { 9 };
    let day_of_year = (153 * shifted_month + 2) / 5 + i64::from(day) - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

fn civil_from_days(days: i64) -> (i32, u32, u32) {
    let shifted = days + 719_468;
    let era = shifted.div_euclid(146_097);
    let day_of_era = shifted - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    year += i64::from(month <= 2);
    (year as i32, month as u32, day as u32)
}

