fn automation_graph_model(workflow: &AutomationWorkflow) -> Result<GraphModel, String> {
    let mut input_ports = BTreeMap::<String, BTreeSet<String>>::new();
    let mut output_ports = BTreeMap::<String, BTreeSet<String>>::new();
    for node in &workflow.draft.nodes {
        if node.kind != "trigger" {
            input_ports
                .entry(node.id.clone())
                .or_default()
                .insert("input".to_owned());
        }
        output_ports
            .entry(node.id.clone())
            .or_default()
            .insert("output".to_owned());
    }
    for edge in &workflow.draft.edges {
        output_ports
            .entry(edge.source.clone())
            .or_default()
            .insert(edge.source_handle.as_deref().unwrap_or("output").to_owned());
        input_ports
            .entry(edge.target.clone())
            .or_default()
            .insert(edge.target_handle.as_deref().unwrap_or("input").to_owned());
    }

    let nodes = workflow
        .draft
        .nodes
        .iter()
        .map(|node| {
            let mut graph_node = CanvasGraphNode::new(
                node.id.clone(),
                node.title.clone(),
                GraphPoint::new(node.position.x as f32, node.position.y as f32),
                GraphSize::new(184.0, 112.0),
            );
            for port in input_ports.get(&node.id).into_iter().flatten() {
                graph_node = graph_node.with_port(GraphPort::new(
                    format!("in:{port}"),
                    port.clone(),
                    GraphPortKind::Input,
                    GraphPortSide::Left,
                ));
            }
            for port in output_ports.get(&node.id).into_iter().flatten() {
                graph_node = graph_node.with_port(GraphPort::new(
                    format!("out:{port}"),
                    port.clone(),
                    GraphPortKind::Output,
                    GraphPortSide::Right,
                ));
            }
            graph_node
        })
        .collect::<Vec<_>>();
    let edges = workflow
        .draft
        .edges
        .iter()
        .map(|edge| {
            let source_handle = edge.source_handle.as_deref().unwrap_or("output");
            let target_handle = edge.target_handle.as_deref().unwrap_or("input");
            CanvasGraphEdge::new(
                edge.id.clone(),
                GraphEndpoint::new(edge.source.clone(), format!("out:{source_handle}")),
                GraphEndpoint::new(edge.target.clone(), format!("in:{target_handle}")),
            )
            .with_label(source_handle)
        })
        .collect::<Vec<_>>();
    GraphModel::new(nodes, edges).map_err(|error| error.to_string())
}

fn architecture_layout_event_committed(event: &GraphCanvasEvent) -> bool {
    matches!(
        event,
        GraphCanvasEvent::ViewportChanged(_) | GraphCanvasEvent::NodePositionChanged { .. }
    )
}

pub(crate) fn architecture_default_viewport(graph: &GraphModel) -> GraphViewport {
    graph
        .bounds()
        .map(|bounds| GraphViewport::fit(bounds, GraphSize::new(900.0, 560.0), 64.0))
        .unwrap_or_default()
}

fn architecture_workspace_layout_value(
    graph_version: i64,
    graph: &GraphModel,
    viewport: GraphViewport,
) -> Value {
    let node_positions = graph
        .nodes()
        .iter()
        .filter(|node| node.position.is_finite())
        .map(|node| (node.id.as_str().to_owned(), node.position))
        .collect();
    serde_json::to_value(ArchitectureWorkspaceLayout {
        schema_version: ARCHITECTURE_WORKSPACE_LAYOUT_SCHEMA_VERSION,
        graph_version,
        viewport: GraphViewport::new(viewport.offset, viewport.zoom),
        node_positions,
    })
    .unwrap_or_else(|_| {
        json!({
            "schemaVersion": ARCHITECTURE_WORKSPACE_LAYOUT_SCHEMA_VERSION,
            "graphVersion": graph_version,
            "viewport": GraphViewport::default(),
            "nodePositions": {},
        })
    })
}

fn restore_architecture_workspace_layout(
    serialized_state: Option<&Value>,
    graph_version: i64,
    graph: &mut GraphModel,
    viewport: &mut GraphViewport,
) -> Result<(), String> {
    let Some(layout) = serialized_state
        .and_then(Value::as_object)
        .and_then(|state| state.get("architectureLayout"))
    else {
        return Ok(());
    };
    let layout: ArchitectureWorkspaceLayout =
        serde_json::from_value(layout.clone()).map_err(|_| "布局记录格式无效".to_owned())?;
    if layout.schema_version != ARCHITECTURE_WORKSPACE_LAYOUT_SCHEMA_VERSION {
        return Err("布局版本不受支持".to_owned());
    }
    if layout.graph_version < 0 || layout.graph_version > graph_version {
        return Err("布局对应的架构版本无效".to_owned());
    }
    if layout.node_positions.len() > MAX_ARCHITECTURE_LAYOUT_NODES {
        return Err("布局节点数量超过限制".to_owned());
    }
    let normalized_viewport = GraphViewport::new(layout.viewport.offset, layout.viewport.zoom);
    if normalized_viewport != layout.viewport
        || layout.viewport.offset.x.abs() > MAX_ARCHITECTURE_LAYOUT_COORDINATE
        || layout.viewport.offset.y.abs() > MAX_ARCHITECTURE_LAYOUT_COORDINATE
    {
        return Err("画布视图范围无效".to_owned());
    }
    if layout.node_positions.values().any(|position| {
        !position.is_finite()
            || position.x.abs() > MAX_ARCHITECTURE_LAYOUT_COORDINATE
            || position.y.abs() > MAX_ARCHITECTURE_LAYOUT_COORDINATE
    }) {
        return Err("节点位置超出有效范围".to_owned());
    }
    let mut restored_graph = graph.clone();
    for (node_id, position) in layout.node_positions {
        let node_id = node_id.into();
        if restored_graph.node(&node_id).is_some() {
            restored_graph
                .set_node_position(&node_id, position)
                .map_err(|error| error.to_string())?;
        }
    }
    *graph = restored_graph;
    *viewport = normalized_viewport;
    Ok(())
}

pub(crate) fn architecture_graph_model(graph: &ProjectArchitectureGraph) -> Result<GraphModel, String> {
    let nodes = graph
        .nodes
        .iter()
        .enumerate()
        .map(|(index, node)| {
            let column = index % 3;
            let row = index / 3;
            CanvasGraphNode::new(
                node.id.clone(),
                node.label.clone(),
                GraphPoint::new(40.0 + column as f32 * 250.0, 40.0 + row as f32 * 170.0),
                GraphSize::new(184.0, 112.0),
            )
            .with_port(GraphPort::new(
                "input",
                "input",
                GraphPortKind::Input,
                GraphPortSide::Left,
            ))
            .with_port(GraphPort::new(
                "output",
                "output",
                GraphPortKind::Output,
                GraphPortSide::Right,
            ))
        })
        .collect::<Vec<_>>();
    let edges = graph
        .edges
        .iter()
        .map(|edge| {
            CanvasGraphEdge::new(
                edge.id.clone(),
                GraphEndpoint::new(edge.from.clone(), "output"),
                GraphEndpoint::new(edge.to.clone(), "input"),
            )
            .with_label(if edge.label.is_empty() {
                edge.edge_type.clone()
            } else {
                edge.label.clone()
            })
        })
        .collect::<Vec<_>>();
    GraphModel::new(nodes, edges).map_err(|error| error.to_string())
}

pub(crate) fn architecture_status_label(status: ArchitectureChangeStatus) -> &'static str {
    match status {
        ArchitectureChangeStatus::Proposed => "已提议",
        ArchitectureChangeStatus::Pending => "待确认",
        ArchitectureChangeStatus::Applied => "已应用",
        ArchitectureChangeStatus::Rejected => "已拒绝",
        ArchitectureChangeStatus::RolledBack => "已回滚",
    }
}

fn project_task_error_message(error: &DesktopApplicationError) -> String {
    match error {
        DesktopApplicationError::ProjectTask(DesktopProjectTaskError::AlreadyRunning {
            ..
        }) => "该项目任务已在运行。".to_owned(),
        DesktopApplicationError::ProjectTask(DesktopProjectTaskError::TaskNotFound { .. }) => {
            "项目任务已发生变化，请刷新后重试。".to_owned()
        }
        DesktopApplicationError::ProjectTask(
            DesktopProjectTaskError::InvalidTaskId(_)
            | DesktopProjectTaskError::DuplicateTaskId(_)
            | DesktopProjectTaskError::InvalidField { .. }
            | DesktopProjectTaskError::InvalidEnvironmentKey(_)
            | DesktopProjectTaskError::UnsupportedVersion(_)
            | DesktopProjectTaskError::TooManyTasks(_)
            | DesktopProjectTaskError::TooManyArguments { .. }
            | DesktopProjectTaskError::TooManyEnvironmentEntries { .. }
            | DesktopProjectTaskError::ConfigTooLarge(_)
            | DesktopProjectTaskError::InvalidConfig { .. },
        ) => "项目任务配置无效，请检查 .lilia/tasks.json。".to_owned(),
        DesktopApplicationError::ProjectTask(DesktopProjectTaskError::ConfigEscapesWorkspace(
            _,
        )) => "项目任务配置必须位于当前工作区。".to_owned(),
        DesktopApplicationError::ProjectTask(DesktopProjectTaskError::ArchivedProject(_)) => {
            "归档项目不能运行任务。".to_owned()
        }
        _ => "暂时无法读取或运行项目任务。".to_owned(),
    }
}

fn git_file_status_label(status: DesktopGitFileStatus) -> &'static str {
    match status {
        DesktopGitFileStatus::Untracked => "未跟踪",
        DesktopGitFileStatus::Modified => "已修改",
        DesktopGitFileStatus::Added => "新增",
        DesktopGitFileStatus::Deleted => "删除",
        DesktopGitFileStatus::Renamed => "重命名",
        DesktopGitFileStatus::Copied => "复制",
        DesktopGitFileStatus::Conflicted => "冲突",
        DesktopGitFileStatus::Ignored => "忽略",
    }
}

fn first_workspace_pane_id(node: &PaneNode) -> &PaneId {
    match node {
        PaneNode::Leaf { id, .. } => id,
        PaneNode::Split { first, .. } => first_workspace_pane_id(first),
    }
}

fn nana_split_axis(axis: SplitAxis) -> NanaSplitAxis {
    match axis {
        SplitAxis::Horizontal => NanaSplitAxis::Horizontal,
        SplitAxis::Vertical => NanaSplitAxis::Vertical,
    }
}

fn usable_workspace_split_extent(extent: f32) -> f32 {
    (extent - WORKSPACE_SPLIT_HANDLE_SIZE).max(1.0)
}

fn collect_workspace_split_specs(
    node: &PaneNode,
    width: f32,
    height: f32,
    specs: &mut Vec<WorkspaceSplitSpec>,
) {
    let PaneNode::Split {
        axis,
        ratio,
        first,
        second,
    } = node
    else {
        return;
    };
    let extent = match axis {
        SplitAxis::Horizontal => width,
        SplitAxis::Vertical => height,
    };
    specs.push(WorkspaceSplitSpec {
        key: WorkspaceSplitKey {
            first_pane_id: first_workspace_pane_id(first).clone(),
            second_pane_id: first_workspace_pane_id(second).clone(),
        },
        axis: *axis,
        ratio: *ratio,
        extent,
    });
    let usable_extent = usable_workspace_split_extent(extent);
    let first_extent = usable_extent * ratio;
    let second_extent = usable_extent - first_extent;
    match axis {
        SplitAxis::Horizontal => {
            collect_workspace_split_specs(first, first_extent, height, specs);
            collect_workspace_split_specs(second, second_extent, height, specs);
        }
        SplitAxis::Vertical => {
            collect_workspace_split_specs(first, width, first_extent, specs);
            collect_workspace_split_specs(second, width, second_extent, specs);
        }
    }
}

fn nana_pane_tree_node(node: &PaneNode) -> PaneTreeNode {
    match node {
        PaneNode::Leaf { id, .. } => PaneTreeNode::leaf(id.as_str()),
        PaneNode::Split {
            axis,
            ratio,
            first,
            second,
        } => PaneTreeNode::split(
            format!(
                "{}:{}",
                first_workspace_pane_id(first).as_str(),
                first_workspace_pane_id(second).as_str()
            ),
            match axis {
                SplitAxis::Horizontal => NanaSplitAxis::Horizontal,
                SplitAxis::Vertical => NanaSplitAxis::Vertical,
            },
            *ratio,
            nana_pane_tree_node(first),
            nana_pane_tree_node(second),
        ),
    }
}

fn reordered_before<T>(values: &[T], source: &T, before: Option<&T>) -> Option<Vec<T>>
where
    T: Clone + PartialEq,
{
    let source_index = values.iter().position(|value| value == source)?;
    let before_index = match before {
        Some(before) => Some(values.iter().position(|value| value == before)?),
        None => None,
    };
    if before_index == Some(source_index) {
        return None;
    }
    let mut reordered = values.to_vec();
    reordered.remove(source_index);
    let insert_at = before
        .and_then(|before| reordered.iter().position(|value| value == before))
        .unwrap_or(reordered.len());
    reordered.insert(insert_at, source.clone());
    (reordered != values).then_some(reordered)
}

fn relative_before_id<T>(
    values: &[T],
    source: &T,
    target: &T,
    position: SidebarTreeDropPosition,
) -> Option<T>
where
    T: Clone + PartialEq,
{
    if source == target || position == SidebarTreeDropPosition::Inside {
        return None;
    }
    let remaining = values
        .iter()
        .filter(|value| *value != source)
        .cloned()
        .collect::<Vec<_>>();
    let target_index = remaining.iter().position(|value| value == target)?;
    match position {
        SidebarTreeDropPosition::Before => Some(target.clone()),
        SidebarTreeDropPosition::After => remaining.get(target_index + 1).cloned(),
        SidebarTreeDropPosition::Inside => None,
    }
}

fn sidebar_folder_drop_hit(bounds: LogicalRect, position: Point) -> bool {
    position.x >= bounds.x
        && position.x <= bounds.x + bounds.width
        && position.y >= bounds.y
        && position.y <= bounds.y + (bounds.height - 56.0).max(0.0)
}

#[cfg(test)]
