    fn workspace_task(id: &str, parent_id: Option<&str>) -> DesktopWorkspaceTask {
        DesktopWorkspaceTask {
            id: TaskId::new(id).unwrap(),
            title: id.to_owned(),
            parent_id: parent_id.map(|parent_id| TaskId::new(parent_id).unwrap()),
            status: ProductTaskStatus::Draft,
            priority: ProductTaskPriority::Normal,
            pinned: false,
            sort_order: 0,
        }
    }

    fn product_task(id: &str, parent_id: Option<&str>) -> ProductTask {
        let mut task = ProductTask::new(TaskId::new(id).unwrap(), None, id).unwrap();
        task.parent_id = parent_id.map(|parent_id| TaskId::new(parent_id).unwrap());
        task
    }

    #[test]
    fn task_tree_orders_parents_before_children_and_bounds_corrupt_cycles() {
        let tasks = vec![
            workspace_task("child", Some("parent")),
            workspace_task("parent", None),
            workspace_task("cycle-a", Some("cycle-b")),
            workspace_task("cycle-b", Some("cycle-a")),
            workspace_task("missing-parent", Some("missing")),
        ];
        let ordered = ordered_task_tree_indices(&tasks)
            .into_iter()
            .map(|(index, depth)| (tasks[index].id.as_str().to_owned(), depth))
            .collect::<Vec<_>>();
        assert_eq!(ordered[0], ("parent".to_owned(), 0));
        assert_eq!(ordered[1], ("child".to_owned(), 1));
        assert_eq!(ordered[2], ("missing-parent".to_owned(), 0));
        assert_eq!(ordered.len(), tasks.len());
        assert!(task_is_descendant_of(
            &tasks,
            &TaskId::new("child").unwrap(),
            &TaskId::new("parent").unwrap()
        ));
        assert!(!task_is_descendant_of(
            &tasks,
            &TaskId::new("parent").unwrap(),
            &TaskId::new("child").unwrap()
        ));
    }

