    fn workspace_split_specs_follow_nested_ratio_geometry() {
        let mut layout = PanelLayoutSnapshot::default();
        let primary = PaneId::new("primary").unwrap();
        let secondary = PaneId::new("secondary").unwrap();
        let nested = PaneId::new("nested").unwrap();
        layout
            .split_pane(&primary, secondary.clone(), SplitAxis::Horizontal, 0.5)
            .unwrap();
        layout
            .split_pane(&primary, nested.clone(), SplitAxis::Vertical, 0.25)
            .unwrap();
        let mut specs = Vec::new();
        collect_workspace_split_specs(&layout.panes, 1_000.0, 800.0, &mut specs);

        assert_eq!(specs.len(), 2);
        assert_eq!(
            specs[0].key,
            WorkspaceSplitKey {
                first_pane_id: primary.clone(),
                second_pane_id: secondary,
            }
        );
        assert_eq!((specs[0].ratio, specs[0].extent), (0.5, 1_000.0));
        assert_eq!(
            specs[1].key,
            WorkspaceSplitKey {
                first_pane_id: primary,
                second_pane_id: nested,
            }
        );
        assert_eq!((specs[1].ratio, specs[1].extent), (0.25, 800.0));
    }

