    #[test]
    fn architecture_workspace_layout_restores_retained_nodes_and_rejects_corruption_atomically() {
        let graph = ProjectArchitectureGraph {
            project_id: "project".to_owned(),
            version: 2,
            summary: String::new(),
            nodes: vec![
                crate::application::ProjectArchitectureNode {
                    id: "ui".to_owned(),
                    label: "UI".to_owned(),
                    node_type: "module".to_owned(),
                    summary: String::new(),
                    paths: Vec::new(),
                    tags: Vec::new(),
                },
                crate::application::ProjectArchitectureNode {
                    id: "new".to_owned(),
                    label: "New".to_owned(),
                    node_type: "module".to_owned(),
                    summary: String::new(),
                    paths: Vec::new(),
                    tags: Vec::new(),
                },
            ],
            edges: Vec::new(),
            updated_at: 2,
        };
        let mut source = architecture_graph_model(&graph).unwrap();
        let ui_id = source.nodes()[0].id.clone();
        source
            .set_node_position(&ui_id, GraphPoint::new(320.0, 180.0))
            .unwrap();
        let saved_viewport = GraphViewport::new(GraphPoint::new(42.0, -18.0), 1.5);
        let state = json!({
            "architectureLayout": architecture_workspace_layout_value(1, &source, saved_viewport)
        });

        let mut restored = architecture_graph_model(&graph).unwrap();
        let new_node_position = restored.nodes()[1].position;
        let mut viewport = GraphViewport::default();
        restore_architecture_workspace_layout(Some(&state), 2, &mut restored, &mut viewport)
            .unwrap();
        assert_eq!(
            restored.node(&ui_id).unwrap().position,
            GraphPoint::new(320.0, 180.0)
        );
        assert_eq!(restored.nodes()[1].position, new_node_position);
        assert_eq!(viewport, saved_viewport);

        let before_graph = restored.clone();
        let before_viewport = viewport;
        let corrupt = json!({
            "architectureLayout": {
                "schemaVersion": 1,
                "graphVersion": 2,
                "viewport": { "offset": { "x": 0.0, "y": 0.0 }, "zoom": 1.0 },
                "nodePositions": { "ui": { "x": 2_000_000.0, "y": 0.0 } }
            }
        });
        assert!(restore_architecture_workspace_layout(
            Some(&corrupt),
            2,
            &mut restored,
            &mut viewport,
        )
        .is_err());
        assert_eq!(restored, before_graph);
        assert_eq!(viewport, before_viewport);
    }

