    #[test]
    fn native_mcp_form_normalizes_free_arrays_and_uses_the_typed_accept_action() {
        let pending = PendingActionView {
            request_id: "request-mcp".to_owned(),
            kind: "mcp_elicitation".to_owned(),
            prompt: "填写发布信息".to_owned(),
            status: PendingProjectionStatus::Open,
            payload: json!({
                "threadId": "task-mcp",
                "serverName": "debug-mcp",
                "mode": "form",
                "requestedSchema": {
                    "type": "object",
                    "required": ["project", "summary"],
                    "properties": {
                        "project": {"type": "string", "enum": ["Alpha", "Beta"]},
                        "summary": {"type": "string"},
                        "tags": {"type": "array"}
                    }
                }
            }),
        };
        let draft = Map::from_iter([
            ("project".to_owned(), Value::String("Beta".to_owned())),
            (
                "summary".to_owned(),
                Value::String("Native ready".to_owned()),
            ),
            (
                "tags".to_owned(),
                Value::String("native, mcp\nrelease".to_owned()),
            ),
        ]);

        let action = pending_mcp_debug_action(
            &pending,
            &target_ids::mcp_accept(&pending.request_id),
            &draft,
        )
        .unwrap();
        let McpDebugAction::Respond {
            accepted, response, ..
        } = action
        else {
            panic!("MCP accept target must produce a typed response");
        };
        assert!(accepted);
        assert_eq!(response["action"], "accept");
        assert_eq!(response["content"]["project"], "Beta");
        assert_eq!(
            response["content"]["tags"],
            json!(["native", "mcp", "release"])
        );
    }

    #[test]
    fn native_mcp_form_keeps_accept_unavailable_until_required_fields_are_valid() {
        let pending = PendingActionView {
            request_id: "request-mcp-invalid".to_owned(),
            kind: "mcp_elicitation".to_owned(),
            prompt: "填写发布信息".to_owned(),
            status: PendingProjectionStatus::Open,
            payload: json!({
                "threadId": "task-mcp",
                "serverName": "debug-mcp",
                "mode": "form",
                "requestedSchema": {
                    "type": "object",
                    "required": ["summary"],
                    "properties": {"summary": {"type": "string"}}
                }
            }),
        };
        let draft = Map::new();

        assert_eq!(
            pending_mcp_debug_action(
                &pending,
                &target_ids::mcp_accept(&pending.request_id),
                &draft,
            ),
            None
        );
        assert!(matches!(
            pending_mcp_debug_action(
                &pending,
                &target_ids::mcp_decline(&pending.request_id),
                &draft,
            ),
            Some(McpDebugAction::Respond {
                accepted: false,
                response,
                ..
            }) if response["action"] == "decline"
        ));
    }

